import{_ as t}from"./chunks/notepad-view.BLad7TUP.js";import{_ as a,H as o,f as n,i}from"./chunks/framework.CSxcEb-0.js";const h=JSON.parse('{"title":"Notepad","description":"","frontmatter":{},"headers":[],"relativePath":"guide/notepad.md","filePath":"guide/notepad.md"}'),r={name:"guide/notepad.md"};function s(d,e,l,p,c,g){return o(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="notepad" tabindex="-1">Notepad <a class="header-anchor" href="#notepad" aria-label="Permalink to &quot;Notepad&quot;">​</a></h1><p>The <strong>Notepad</strong> view is a lightweight scratchpad for planning context alongside tasks and calendar.</p><p><img src="'+t+'" alt="Notepad view"></p><h2 id="single-page-mode-default" tabindex="-1">Single-page mode (default) <a class="header-anchor" href="#single-page-mode-default" aria-label="Permalink to &quot;Single-page mode (default)&quot;">​</a></h2><p>One continuous note area. Good for daily plans, scratch lists, and meeting notes without managing multiple documents.</p><h2 id="multi-page-mode" tabindex="-1">Multi-page mode <a class="header-anchor" href="#multi-page-mode" aria-label="Permalink to &quot;Multi-page mode&quot;">​</a></h2><p>Enable <strong>multiple notepad pages</strong> in <strong>Settings → Theme → Notepad</strong>. You get:</p><ul><li>A sidebar of named pages</li><li>Separate content per page for topics (projects, weekly review, etc.)</li></ul><h2 id="markdown-formatting" tabindex="-1">Markdown formatting <a class="header-anchor" href="#markdown-formatting" aria-label="Permalink to &quot;Markdown formatting&quot;">​</a></h2><p>On by default (<strong>Settings → Theme → Notepad → Markdown formatting</strong>). Notes are stored as Markdown plain text (compatible with existing plain notes).</p><p>Supported syntax includes:</p><ul><li><strong>Headings</strong> (<code>#</code>, <code>##</code>, …)</li><li><strong>Bold</strong>, <em>italic</em>, <code>inline code</code></li><li>Bullet and numbered lists</li><li>Task checkboxes (<code>- [ ]</code> / <code>- [x]</code>) via GitHub-flavored Markdown</li><li>Links, blockquotes, tables, and fenced code blocks</li></ul><p>Use the toolbar to insert common Markdown, or type it directly in <strong>Edit</strong> mode.</p><h3 id="preview-modes" tabindex="-1">Preview modes <a class="header-anchor" href="#preview-modes" aria-label="Permalink to &quot;Preview modes&quot;">​</a></h3><ul><li><strong>Edit</strong> — source Markdown with the dotted notepad background</li><li><strong>Preview</strong> — rendered note (switch back to edit to change text)</li><li><strong>Split</strong> — source and preview side by side on wider screens</li></ul><p>Turn <strong>Markdown formatting</strong> off to hide the toolbar and use a plain text area only.</p><h2 id="create-a-task-from-a-line" tabindex="-1">Create a task from a line <a class="header-anchor" href="#create-a-task-from-a-line" aria-label="Permalink to &quot;Create a task from a line&quot;">​</a></h2><p>Turn a scratch line into a task without retyping:</p><ol><li>Use <strong>Edit</strong> mode (not Preview-only).</li><li>Place the caret on a <strong>non-empty</strong> line (works in single-page and multi-page mode).</li><li><strong>Right-click</strong> the note area.</li></ol><p>TemPad opens the task editor with the line’s text as the <strong>title</strong> (Markdown markers like <code>#</code> or <code>- [ ]</code> are stripped). Set due date, duration, list, and save as usual.</p><h2 id="persistence" tabindex="-1">Persistence <a class="header-anchor" href="#persistence" aria-label="Permalink to &quot;Persistence&quot;">​</a></h2><p>Notepad content is saved with your app state:</p><ul><li><strong>Local mode:</strong> browser storage</li><li><strong>Signed in:</strong> Firestore sync across devices</li></ul><p>Notepad does not participate in auto-scheduling — it is reference material only.</p>',24)])])}const f=a(r,[["render",s]]);export{h as __pageData,f as default};
